#!/usr/bin/env bash
# Autogenerated test: runs inside a container built from each compatibility image with freecad installed with default
# options, as the image's remote user, and also as root through sudo when the remote user is not root.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

# Succeeds when FreeCAD's per-user directories resolve under HOME and hold no add-on of the user's.
fresh_user_defaults() {
  cat >"${SCRATCH}/fresh.py" <<'PY'
import os
import sys

import FreeCAD

home = os.path.expanduser("~")
problems = []
for path in (FreeCAD.getUserAppDataDir(), FreeCAD.getUserConfigDir(), FreeCAD.getUserMacroDir()):
    if not path.startswith(home + os.sep):
        problems.append("%s is outside %s" % (path, home))
if os.path.exists(os.path.join(FreeCAD.getUserAppDataDir(), "Mod")):
    problems.append("the user already has add-ons")
if not FreeCAD.getHomePath().startswith("/opt/freecad/"):
    problems.append("FreeCAD runs from %s" % FreeCAD.getHomePath())
if problems:
    print("PROBLEMS", problems)
    sys.stdout.flush()
    sys.exit(3)
PY
  timeout "${LIMIT}" freecadcmd "${SCRATCH}/fresh.py" >"${SCRATCH}/fresh.log" 2>&1 || {
    cat "${SCRATCH}/fresh.log" >&2
    return 1
  }
}

# The installation ran FreeCAD as root to check it; none of FreeCAD's per-user directories may come from that.
check "the installation left no FreeCAD state in the user's home" home_has_no_freecad_state
if [[ "$(id -u)" != 0 ]]; then
  check "the installation left no FreeCAD state in root's home" home_has_no_freecad_state sudo -n
fi

before="$(tree_manifest)"
latest="$(newest_release)"

check "freecadcmd reports the newest stable release" reports_release "${latest}"
check "the marker records the installed release" marker_records "${latest}"
check "freecad and freecadcmd link to the launchers" links_target_launchers
check "the feature adds no other command" adds_two_commands
check "the bundled Gmsh, CalculiX, and pip stay off PATH" \
  bash -c '! command -v gmsh && ! command -v ccx && ! command -v pip'
check "the installation belongs to root and only root can write it" tree_is_root_only
check "the downloaded AppImage is not kept" \
  bash -c '! compgen -G "/opt/.freecad-feature.*" && ! compgen -G "/opt/freecad/*.AppImage"'
check "a first start keeps FreeCAD's defaults" fresh_user_defaults
check "a script models a solid and exports STEP and STL" models_and_exports
check "a script's sys.exit status reaches the caller" exit_status_reaches_caller
check "an uncaught exception alone leaves the exit status 0" uncaught_exception_exits_zero
check "the notes' command-line example writes its output, and exits non-zero when it raises" \
  notes_example_follows_script
check "the launchers set five variables and no library or Python path" test "$(child_environment)" = \
  "FONTCONFIG_FILE=/etc/fonts/fonts.conf
FONTCONFIG_PATH=/etc/fonts
GIT_SSL_CAINFO=/opt/freecad/usr/ssl/cacert.pem
QT_QPA_PLATFORM=xcb
SSL_CERT_FILE=/opt/freecad/usr/ssl/cacert.pem"
check "the launchers keep the caller's values, an empty one included" \
  test "$(child_environment QT_QPA_PLATFORM=offscreen SSL_CERT_FILE=/caller/ca.pem FONTCONFIG_PATH=)" = \
  "FONTCONFIG_FILE=/etc/fonts/fonts.conf
FONTCONFIG_PATH=
GIT_SSL_CAINFO=/opt/freecad/usr/ssl/cacert.pem
QT_QPA_PLATFORM=offscreen
SSL_CERT_FILE=/caller/ca.pem"
check "the image's fontconfig configuration and a font exist" fonts_are_configured
check "no display server is installed" bash -c '! command -v Xorg && ! command -v Xvfb && ! command -v Xvnc'
check "no Vulkan driver is installed" bash -c '! compgen -G "/usr/share/vulkan/icd.d/*.json"'
check "freecad fails without a display, as upstream's build does" gui_fails_without_display
check "freecad runs a script on the offscreen platform" gui_runs_offscreen
if [[ "$(id -u)" != 0 ]]; then
  check "root reports the newest stable release" reports_release "${latest}" sudo -n
  check "root models a solid and exports STEP and STL" models_and_exports sudo -n
fi
check "running FreeCAD leaves the installation tree unchanged" test "$(tree_manifest)" = "${before}"

# The feature provides no display, so the test brings its own X server for the GUI checks.
check "an X server starts for the GUI checks" start_x_server
check "the notes' GUI example renders a 3D view through the X server" gui_renders_view
if [[ "$(id -u)" != 0 ]]; then
  check "root renders a 3D view through the X server" gui_renders_view sudo -n
fi
check "rendering leaves the installation tree unchanged" test "$(tree_manifest)" = "${before}"

reportResults
